  if (MessageEncoder_encoding_tison(self) || !ByteArray_has_owned_external_memory(object)) {
    return MessageEncoder_encode_copy(self, object, (int)TAG_BYTE_ARRAY);
  }
  //@ open encoder(self, ids);
